@media print {
  table {
    width: 100%;
    border-collapse: collapse;
}

thead {
    display: table-header-group !important;
    /* Ensures headers are repeated on each page */
}

tfoot {
    display: table-footer-group !important;
    /* Ensures footers are repeated on each page */
}

tbody {
    display: table-row-group !important;
}
}

@font-face {
  font-family: 'Stencil';
  src: url('fonts/Stencil.ttf') format('truetype'); /* Make sure the path is correct */
}

.absolute{
   position:absolute;

}
}
@media print {
  tfoot{
    position: fixed;
    bottom: 0;
    width: 100%;
  }

  table {
    page-break-inside: auto;
  }

  tr {
    page-break-inside: avoid;
    page-break-after: auto;
  }
}
